def choose_role(self, state: AgentState) -> str:
    failures = state.consecutive_failures
    if failures >= 5 and self._enabled("remote"):
        return "remote"
    if failures >= 3 and self._enabled("large"):
        return "large"
    if state.history and state.history[-1].tool in {"list_files", "read_file", "search_text"}:
        if self._enabled("small"):
            return "small"
    return "main"

