def completion_with_fallback(self, role: str, system: str, user: str) -> tuple[str, str]:
    order = [role]
    for fallback in ("large", "main", "small"):
        if fallback not in order and self._enabled(fallback):
            order.append(fallback)
    last_error: Exception | None = None
    for candidate in order:
        try:
            return candidate, self.backend(candidate).complete(system, user)
        except Exception as exc:
            last_error = exc
            print(f"[MODEL] {candidate} unavailable: {exc}")
    raise HelixError(f"No model backend succeeded: {last_error}")

